// On récupère la chaine HEX spécifiquement dans l'objet
let hexString = "";

if (msg.payload && msg.payload.hex) {
    hexString = msg.payload.hex;
} else if (typeof msg.payload === 'string') {
    hexString = msg.payload;
}

// Timestamp actuel (Date du serveur)
const timestamp = Math.floor(Date.now() / 1000);

// ID (soit celui du message, soit 1 par défaut)
