};

return msg;

// ========== CLE XTEA ==========
// VERIFIEZ QUE CETTE CLE EST IDENTIQUE A L'ARDUINO
const XTEA_KEY = [0xA1B2C3D4, 0xE5F67890, 0x1A2B3C4D, 0x5E6F7809];

// ========== ALGORYTHME ==========
function xteaDec(v) {
    let v0 = v[0], v1 = v[1];
    const delta = 0x9E3779B9;
    let sum = delta * 32;

    for (let i = 0; i < 32; i++) {
        v1 -= (((v0 << 4) ^ (v0 >>> 5)) + v0) ^ (sum + XTEA_KEY[(sum >>> 11) & 3]);
        v1 = v1 >>> 0;
        sum -= delta;
        sum = sum >>> 0;
        v0 -= (((v1 << 4) ^ (v1 >>> 5)) + v1) ^ (sum + XTEA_KEY[sum & 3]);
        v0 = v0 >>> 0;
    }
    return [v0, v1];
}

function decryptMessage(hex) {
    if (!hex || typeof hex !== 'string') return "";
    let out = "";

    for (let i = 0; i < hex.length; i += 16) {
        let sub = hex.substring(i, i + 16);
        if (sub.length < 16) break;

        let b = [
            parseInt(sub.substring(0, 8), 16),
            parseInt(sub.substring(8, 16), 16)
        ];

        b = xteaDec(b);

        // Conversion en caractères
        for (let k = 0; k < 2; k++) {
            for (let j = 0; j < 4; j++) {
                // Note: Si le résultat est du charabia, essayez de changer
                // (j * 8) en ((3-j) * 8) ici (Endianness)
                let byte = (b[k] >>> (j * 8)) & 0xFF;
                if (byte !== 0) out += String.fromCharCode(byte);
            }
        }
    }
    return out.trim();
}

function extractValue(data, key) {
    if (!data) return null;
    const s = data.indexOf(key);
    if (s === -1) return null;
    const start = s + key.length;
    let end = data.indexOf(';', start);
    if (end === -1) end = data.length;
    return data.substring(start, end);
}

// ========== EXECUTION ==========
try {
    const decrypted = decryptMessage(msg.payload.hex);

    // Extraction des valeurs avec sécurité (|| 0)
    msg.payload.decrypted_raw = decrypted;
    msg.payload.temperature = parseFloat(extractValue(decrypted, "T="));
    msg.payload.humidite = parseFloat(extractValue(decrypted, "H="));
    msg.payload.sol = parseInt(extractValue(decrypted, "S="));
    msg.payload.lumiere = parseInt(extractValue(decrypted, "L="));

    // Vérification si le décodage a marché
    msg.payload.success = !isNaN(msg.payload.temperature);

    return msg;
